(4416535, 636849, 55892, '<td valign="top">Excellent in black &amp; white.  Did it work with shoelaces too?  I always used a string!</td>', 'Excellent in black & white.  Did it work with shoelaces too?  I always used a string!', '2008-01-23 06:21:33.000000', NULL, 1),
(4416536, 635513, 88010, '<td valign="top">so your the one that broke it.</td>', 'so your the one that broke it.', '2008-01-23 06:21:53.000000', NULL, 1),
(4416539, 634949, 88010, '<td valign="top">the playing cards on the front threw this over the edge and make it look set-up. And the newspaper through the stearing wheel too. the dirt and sticks and debris on the seat look normal.</td>', 'the playing cards on the front threw this over the edge and make it look set-up. And the newspaper through the stearing wheel too. the dirt and sticks and debris on the seat look normal.', '2008-01-23 06:23:39.000000', NULL, 1),
(4416542, 636707, 88010, '<td valign="top">This would be stronger without the sky. That bright sky pulls the eye away from the real subject.</td>', 'This would be stronger without the sky. That bright sky pulls the eye away from the real subject.', '2008-01-23 06:24:53.000000', NULL, 1),
