(4416545, 635345, 88204, '<td valign="top">Ah yes! Definitely a childhood memory! I like the close crop and choice to focus on just the dice.</td>', 'Ah yes! Definitely a childhood memory! I like the close crop and choice to focus on just the dice.', '2008-01-23 06:25:41.000000', NULL, 1),
(4416546, 636838, 88010, '<td valign="top">Gee I haven''t seen on eof these in years. Around hee they have all been removed for liability reasons.<br/>Nice motion shot.</td>', 'Gee I haven''t seen on eof these in years. Around hee they have all been removed for liability reasons.Nice motion shot.', '2008-01-23 06:26:22.000000', NULL, 1),
(4416547, 636307, 77543, '<td valign="top">I can''t tell what this is.</td>', 'I can''t tell what this is.', '2008-01-23 06:27:26.000000', NULL, 1),
