(4417062, 634155, 86447, '<td valign="top">I wish there was more light on the underside of the plane, since that''s the view we''re given.</td>', 'I wish there was more light on the underside of the plane, since that''s the view we''re given.', '2008-01-23 09:39:47.000000', NULL, 1),
(4417064, 637067, 33446, '<td valign="top">Wonderful...colorful and memorable</td>', 'Wonderful...colorful and memorable', '2008-01-23 09:40:04.000000', NULL, 1),
(4417067, 635716, 86447, '<td valign="top">I wish there was something large to give this playhouse (I assume) some scale.  It''s so charming and well done that it appears to be full size.</td>', 'I wish there was something large to give this playhouse (I assume) some scale.  It''s so charming and well done that it appears to be full size.', '2008-01-23 09:41:12.000000', NULL, 1),
(4417071, 635338, 86447, '<td valign="top">White balance adjustment could make this POP more... but it''s a fun shot.</td>', 'White balance adjustment could make this POP more... but it''s a fun shot.', '2008-01-23 09:42:36.000000', NULL, 1),
(4417076, 636083, 86447, '<td valign="top">The background being so in focus really distracts my eyes from the subject.  A shallower depth of field would have worked better, in my opinion.  Cute, though.  :)</td>', 'The background being so in focus really distracts my eyes from the subject.  A shallower depth of field would have worked better, in my opinion.  Cute, though.  :)', '2008-01-23 09:43:47.000000', NULL, 1),
