(4417083, 637104, 86447, '<td valign="top">The well lit hat against the not well lit inside of the glove lead me to believe that the lighting could have been improved to make the hat not seem to steal all the attention in the shot.</td>', 'The well lit hat against the not well lit inside of the glove lead me to believe that the lighting could have been improved to make the hat not seem to steal all the attention in the shot.', '2008-01-23 09:44:43.000000', NULL, 1),
