(4418577, 634503, 88204, '<td valign="top">Ah yes... the dreaded magnifying glass. Great memory. I might like a lower, closer angle or even better... showing the actual burning in process with the rays of the magnifier and some smoke and burning plastic.</td>', 'Ah yes... the dreaded magnifying glass. Great memory. I might like a lower, closer angle or even better... showing the actual burning in process with the rays of the magnifier and some smoke and burning plastic.', '2008-01-23 17:42:53.000000', NULL, 1),
(4418579, 637114, 68947, '<td valign="top">I STILL love seeing these shows!  Wonder if I''m going through my second childhood? *grin*</td>', 'I STILL love seeing these shows!  Wonder if I''m going through my second childhood? *grin*', '2008-01-23 17:43:00.000000', NULL, 1),
(4418585, 636386, 68947, '<td valign="top">Love the composition!</td>', 'Love the composition!', '2008-01-23 17:43:42.000000', NULL, 1),
(4418587, 634155, 88204, '<td valign="top">Good childhood memory. The image isn''t particulary inspiring on it''s own. Maybe a more dramatic sky or motion on the prop or a pan to show motion.</td>', 'Good childhood memory. The image isn''t particulary inspiring on it''s own. Maybe a more dramatic sky or motion on the prop or a pan to show motion.', '2008-01-23 17:44:01.000000', NULL, 1),
(4418599, 637096, 88204, '<td valign="top">Nice color! I wish they were a tad sharper. The white edges are so bright they distract a bit. How about a lone drip of juice in the white space? That would give us another point of interest to ponder.</td>', 'Nice color! I wish they were a tad sharper. The white edges are so bright they distract a bit. How about a lone drip of juice in the white space? That would give us another point of interest to ponder.', '2008-01-23 17:45:25.000000', NULL, 1),
(4418602, 634398, 68947, '<td valign="top">Not quite sure what it is about this shot that could improve it.  Perhaps, it''s the angle and the blur to the swing motion????</td>', 'Not quite sure what it is about this shot that could improve it.  Perhaps, it''s the angle and the blur to the swing motion????', '2008-01-23 17:46:05.000000', NULL, 1),
(4418603, 634081, 88204, '<td valign="top">I like the movement of the hand. Lighting is warm and even.</td>', 'I like the movement of the hand. Lighting is warm and even.', '2008-01-23 17:46:10.000000', NULL, 1),
(4418605, 637043, 88204, '<td valign="top">Great color!</td>', 'Great color!', '2008-01-23 17:46:28.000000', NULL, 1),
(4418607, 637097, 68947, '<td valign="top">Love the antique-misty focus as it does make it seem like a memory.  Nice spin to a challenge that holds so many playground shots!</td>', 'Love the antique-misty focus as it does make it seem like a memory.  Nice spin to a challenge that holds so many playground shots!', '2008-01-23 17:46:54.000000', NULL, 1),
(4418610, 637040, 88204, '<td valign="top">Fake animals like this are almost eerie... kind of like clowns. Great color. I like the composition focusing on the two faces.</td>', 'Fake animals like this are almost eerie... kind of like clowns. Great color. I like the composition focusing on the two faces.', '2008-01-23 17:47:24.000000', NULL, 1),
