(4420526, 634081, 71608, '<td valign="top">Good idea! Just a suggestion - tilting the head back to see the doll''s face better would have drawn me into the scene better :)</td>', 'Good idea! Just a suggestion - tilting the head back to see the doll''s face better would have drawn me into the scene better :)', '2008-01-24 08:10:16.000000', NULL, 1),
(4420529, 636737, 71608, '<td valign="top">Great lights and reflections!</td>', 'Great lights and reflections!', '2008-01-24 08:11:39.000000', NULL, 1),
(4420531, 636451, 59293, '<td valign="top">Really captures the game. The colors are so vibrant against the background.</td>', 'Really captures the game. The colors are so vibrant against the background.', '2008-01-24 08:11:59.000000', NULL, 1),
(4420534, 636973, 71608, '<td valign="top">Great definition, good subtle use of (I think) HDR :) Lovely!</td>', 'Great definition, good subtle use of (I think) HDR :) Lovely!', '2008-01-24 08:13:33.000000', NULL, 1),
(4420535, 637075, 59293, '<td valign="top">Looks lonely without children. Great choice to use B&amp;W, let the children add the color.</td>', 'Looks lonely without children. Great choice to use B&W, let the children add the color.', '2008-01-24 08:14:05.000000', NULL, 1),
(4420537, 636826, 59293, '<td valign="top">Nice portrait work,</td>', 'Nice portrait work,', '2008-01-24 08:15:20.000000', NULL, 1),
