(4425350, 634444, 49763, '<td valign="top">The colors and compaosition are striking, well done and beautiful. The image is, however, a little noisy for my taste; there are abundantly grainy portions of the slinky red, indigo and violit bands.</td>', 'The colors and compaosition are striking, well done and beautiful. The image is, however, a little noisy for my taste; there are abundantly grainy portions of the slinky red, indigo and violit bands.', '2008-01-25 21:26:17.000000', NULL, 1),
(4425351, 635826, 87808, '<td valign="top">I know they are monkey handles, but they are kinda looking like handcuffs from this angle</td>', 'I know they are monkey handles, but they are kinda looking like handcuffs from this angle', '2008-01-25 21:26:25.000000', NULL, 1),
(4425357, 634860, 87808, '<td valign="top">How did you get your legs in??? Good take on the challenge</td>', 'How did you get your legs in??? Good take on the challenge', '2008-01-25 21:27:43.000000', NULL, 1),
(4425359, 635345, 49763, '<td valign="top">What I like about this picture most is how well the image coupled with the title applies to my own childhood. Monopoly takes such a long time to play. I like the close up image; the perfectly focused die and the colors. The whole board appears to be titled a little to the left however.</td>', 'What I like about this picture most is how well the image coupled with the title applies to my own childhood. Monopoly takes such a long time to play. I like the close up image; the perfectly focused die and the colors. The whole board appears to be titled a little to the left however.', '2008-01-25 21:28:29.000000', NULL, 1),
(4425360, 635314, 87808, '<td valign="top">How did you get so high!  I feel like that too sometimes!</td>', 'How did you get so high!  I feel like that too sometimes!', '2008-01-25 21:28:48.000000', NULL, 1),
(4425364, 634949, 49763, '<td valign="top">The playing cards are a nice touch. The light and colors of the image are also well rendered. The image is a little small however.</td>', 'The playing cards are a nice touch. The light and colors of the image are also well rendered. The image is a little small however.', '2008-01-25 21:30:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4425367, 635659, 87808, '<td valign="top">Broken childhood through alcoholism?? If it is not that, then I do not get it, sorry.</td>', 'Broken childhood through alcoholism?? If it is not that, then I do not get it, sorry.', '2008-01-25 21:31:33.000000', NULL, 1),
(4425375, 636495, 49763, '<td valign="top">I love the concept. The way in which you have appeared to use a long exposure time to capture the situattion is this dimly lit room is really impressive. I like such details as the shadow cast by the power cord on the left-hand wall and the pure whiteness a la portal surrounding the night light. I am a little confused as to the identity of the blur to the right of the power socket and wonder if the picture could have been completed without it.</td>', 'I love the concept. The way in which you have appeared to use a long exposure time to capture the situattion is this dimly lit room is really impressive. I like such details as the shadow cast by the power cord on the left-hand wall and the pure whiteness a la portal surrounding the night light. I am a little confused as to the identity of the blur to the right of the power socket and wonder if the picture could have been completed without it.', '2008-01-25 21:34:11.000000', NULL, 1),
(4425380, 636609, 49763, '<td valign="top">This one is very amusing. I love that you have a genuine Red Ryder air rifle. The border, the shape and the depth of field are all pluses for me. The target and the dogs in the distance are well chosen as are the stump and the location with the fallen leaves. Good work.</td>', 'This one is very amusing. I love that you have a genuine Red Ryder air rifle. The border, the shape and the depth of field are all pluses for me. The target and the dogs in the distance are well chosen as are the stump and the location with the fallen leaves. Good work.', '2008-01-25 21:36:47.000000', NULL, 1),
(4425405, 637043, 49763, '<td valign="top">Wow! Exuberant! The colors are brillant to say the least. The pink carpet and toy box really complete the unity of brigtness you have created. I really did not realize small children''s toys were this bright. It''s a great shot.</td>', 'Wow! Exuberant! The colors are brillant to say the least. The pink carpet and toy box really complete the unity of brigtness you have created. I really did not realize small children''s toys were this bright. It''s a great shot.', '2008-01-25 21:44:39.000000', NULL, 1),
(4425409, 637104, 49763, '<td valign="top">I am impressed with the lighting and the subject matter. The shadows on the glove are my favroite part of this image. I do not, however, appreciate your border, it seems to detract form the redness of the cap.</td>', 'I am impressed with the lighting and the subject matter. The shadows on the glove are my favroite part of this image. I do not, however, appreciate your border, it seems to detract form the redness of the cap.', '2008-01-25 21:46:38.000000', NULL, 1),
(4425413, 636877, 49763, '<td valign="top">It''s uncanny what life-like expressions this two stuffed animals have. I have always felt that stuffed animals always make better subjects in a apicture than any sort of ceramic figurine. The color unification is another large plus for me. Good job.</td>', 'It''s uncanny what life-like expressions this two stuffed animals have. I have always felt that stuffed animals always make better subjects in a apicture than any sort of ceramic figurine. The color unification is another large plus for me. Good job.', '2008-01-25 21:48:27.000000', NULL, 1),
(4425417, 636320, 49763, '<td valign="top">The movement blur is exciting but generally the image is a little hard to focus on.</td>', 'The movement blur is exciting but generally the image is a little hard to focus on.', '2008-01-25 21:49:17.000000', NULL, 1),
(4425423, 634235, 49763, '<td valign="top">I wish that this image was in color or at least not as bleached out from the left. I like the choice of subject though.</td>', 'I wish that this image was in color or at least not as bleached out from the left. I like the choice of subject though.', '2008-01-25 21:50:34.000000', NULL, 1),
(4425432, 635282, 49763, '<td valign="top">I''ll trust you that this is really from the point of view of a child although it seems a little low to me. I notice that the slide is crocked wheras the horizon is straight - I guess it could not have been helped. The grandiented sky is great as is the choice of tone.</td>', 'I''ll trust you that this is really from the point of view of a child although it seems a little low to me. I notice that the slide is crocked wheras the horizon is straight - I guess it could not have been helped. The grandiented sky is great as is the choice of tone.', '2008-01-25 21:53:25.000000', NULL, 1),
(4425438, 636465, 49763, '<td valign="top">The studio lighting is impressive but there is a little too much dead space on top for my taste.</td>', 'The studio lighting is impressive but there is a little too much dead space on top for my taste.', '2008-01-25 21:55:56.000000', NULL, 1),
(4425439, 636707, 49763, '<td valign="top">I don''t understand the title but perhaps that is my shortcomming. The vertical lines of the trees in the backgorund suit the image well.</td>', 'I don''t understand the title but perhaps that is my shortcomming. The vertical lines of the trees in the backgorund suit the image well.', '2008-01-25 21:56:03.000000', NULL, 1),
(4425441, 636743, 49763, '<td valign="top">This is a cute and well executed image.</td>', 'This is a cute and well executed image.', '2008-01-25 21:56:26.000000', NULL, 1),
(4425443, 637079, 49763, '<td valign="top">The title is clever but the image is a little cluttered.</td>', 'The title is clever but the image is a little cluttered.', '2008-01-25 21:57:10.000000', NULL, 1),
(4425444, 637030, 24974, '<td valign="top">The color of the macaroni looks a bit over-saturated. Nice shot otherwise.</td>', 'The color of the macaroni looks a bit over-saturated. Nice shot otherwise.', '2008-01-25 21:57:14.000000', NULL, 1),
(4425447, 635750, 49763, '<td valign="top">The angle makes me feel like I''m falling forward and I''m not sure if I like that. Otherwise, the tone and concept are great.</td>', 'The angle makes me feel like I''m falling forward and I''m not sure if I like that. Otherwise, the tone and concept are great.', '2008-01-25 21:58:15.000000', NULL, 1),
(4425449, 636557, 49763, '<td valign="top">The depth of field is spot on. The border is flawlessly integrated with the image as a whole, a perfect accent. Well done.</td>', 'The depth of field is spot on. The border is flawlessly integrated with the image as a whole, a perfect accent. Well done.', '2008-01-25 21:59:33.000000', NULL, 1),
(4425450, 636890, 24974, '<td valign="top">This shot needs more contrast. The colors should be much more vivid.</td>', 'This shot needs more contrast. The colors should be much more vivid.', '2008-01-25 21:59:48.000000', NULL, 1),
(4425452, 635692, 49763, '<td valign="top">The lighting is a little harsh on the face of the doll. The simplicity of the picture, however, is a positive.</td>', 'The lighting is a little harsh on the face of the doll. The simplicity of the picture, however, is a positive.', '2008-01-25 22:00:25.000000', NULL, 1),
(4425456, 635495, 49763, '<td valign="top">The whole image is falling to the right. This image would have benefited greatly from a flatter angle, that is, without the slopping floor.</td>', 'The whole image is falling to the right. This image would have benefited greatly from a flatter angle, that is, without the slopping floor.', '2008-01-25 22:01:32.000000', NULL, 1),
(4425473, 636742, 49763, '<td valign="top">I just don''t understand how you managed your colors while abiding by the editing rules. It''s certainly a beautiful image with a well chosen border.</td>', 'I just don''t understand how you managed your colors while abiding by the editing rules. It''s certainly a beautiful image with a well chosen border.', '2008-01-25 22:09:34.000000', NULL, 1),
(4425476, 636953, 49763, '<td valign="top">It''s such a fun and interesting image but really noisy.</td>', 'It''s such a fun and interesting image but really noisy.', '2008-01-25 22:10:16.000000', NULL, 1),
(4425481, 637024, 49763, '<td valign="top">This really limited depth of field is well chosen for the subject, it draws the viewer''s attention to the blue stone very effectivly.</td>', 'This really limited depth of field is well chosen for the subject, it draws the viewer''s attention to the blue stone very effectivly.', '2008-01-25 22:16:13.000000', NULL, 1),
(4425488, 636292, 49763, '<td valign="top">Really powerful and impressive infored photography.</td>', 'Really powerful and impressive infored photography.', '2008-01-25 22:22:32.000000', NULL, 1),
(4425493, 635659, 49763, '<td valign="top">I''m not sure what you''re attempting. Inevitable I think many people will be confused.</td>', 'I''m not sure what you''re attempting. Inevitable I think many people will be confused.', '2008-01-25 22:25:47.000000', NULL, 1),
(4425495, 637030, 49763, '<td valign="top">You sucessfuly captured apetising. Great colors as well.</td>', 'You sucessfuly captured apetising. Great colors as well.', '2008-01-25 22:26:30.000000', NULL, 1),
(4425498, 636735, 49763, '<td valign="top">I really like your focus on the sycamore. It is not only unusual but somehow appropriate for the cahllenge.</td>', 'I really like your focus on the sycamore. It is not only unusual but somehow appropriate for the cahllenge.', '2008-01-25 22:29:17.000000', NULL, 1),
