(4425508, 637098, 49763, '<td valign="top">That is an aweful shirt but you know that already. This is actaully a fun picture but with a few flaws such as the light refraction.</td>', 'That is an aweful shirt but you know that already. This is actaully a fun picture but with a few flaws such as the light refraction.', '2008-01-25 22:33:22.000000', NULL, 1),
(4425509, 634398, 24974, '<td valign="top">Clever title. Like the angle too.</td>', 'Clever title. Like the angle too.', '2008-01-25 22:33:48.000000', NULL, 1),
(4425512, 637072, 24974, '<td valign="top">There is something very disturbing about this shot. Mommy Dearest springs to mind. Technically well done, but disturbing.</td>', 'There is something very disturbing about this shot. Mommy Dearest springs to mind. Technically well done, but disturbing.', '2008-01-25 22:34:43.000000', NULL, 1),
