(4437411, 637108, 2158, '<td valign="top">Nice idea, but it all looks too tidy.  One item only, lying upside down or sideways would have had me more convinced.</td>', 'Nice idea, but it all looks too tidy.  One item only, lying upside down or sideways would have had me more convinced.', '2008-01-29 18:47:30.000000', NULL, 1),
(4437413, 636842, 83416, '<td valign="top">Image appears dark to me.</td>', 'Image appears dark to me.', '2008-01-29 18:48:06.000000', NULL, 1),
(4437418, 636735, 83416, '<td valign="top">Nice idea for the challenge. But, if not for the title it would have been difficult to see the shoes part  not aware if it was possible or not to zoom in or be closer to the subject.</td>', 'Nice idea for the challenge. But, if not for the title it would have been difficult to see the shoes part  not aware if it was possible or not to zoom in or be closer to the subject.', '2008-01-29 18:51:09.000000', NULL, 1),
(4437426, 636815, 83416, '<td valign="top">Nice composition  for me creates a feeling of something forgotten about/left behind. Also - I would have preferred a slightly different color tone (less blues and greens) for such an image.</td>', 'Nice composition  for me creates a feeling of something forgotten about/left behind. Also - I would have preferred a slightly different color tone (less blues and greens) for such an image.', '2008-01-29 18:59:35.000000', NULL, 1),
(4437438, 637117, 83416, '<td valign="top">One of my favorite shots in this challenge  unfortunately there is nothing one can do about those wires. Hope this does very well!!!</td>', 'One of my favorite shots in this challenge  unfortunately there is nothing one can do about those wires. Hope this does very well!!!', '2008-01-29 19:02:07.000000', NULL, 1),
(4437446, 635119, 83416, '<td valign="top">They are all cute!!! Like the choice of B&amp;W. Hope it does well!!!</td>', 'They are all cute!!! Like the choice of B&W. Hope it does well!!!', '2008-01-29 19:03:56.000000', NULL, 1),
(4437451, 636898, 83416, '<td valign="top">I may have gotten rid of the door in the foreground  otherwise a cool shot and believe it will do nicely!!!</td>', 'I may have gotten rid of the door in the foreground  otherwise a cool shot and believe it will do nicely!!!', '2008-01-29 19:05:57.000000', NULL, 1),
(4437456, 636495, 83416, '<td valign="top">Interesting idea for the challenge  not sure why you decided not to crop out the left wall, without which the image would have more spooky effect. Hope it does well.</td>', 'Interesting idea for the challenge  not sure why you decided not to crop out the left wall, without which the image would have more spooky effect. Hope it does well.', '2008-01-29 19:08:59.000000', NULL, 1),
