(4437461, 636815, 24550, '<td valign="top">i see what you were going for here, a desolate kind of feel. the colors accomplish it, but overall, if you had made the tricycle smaller in the frame, i think it would be more effective. good image.</td>', 'i see what you were going for here, a desolate kind of feel. the colors accomplish it, but overall, if you had made the tricycle smaller in the frame, i think it would be more effective. good image.', '2008-01-29 19:10:27.000000', NULL, 1),
(4437464, 636601, 83416, '<td valign="top">Just a thought  image may have been even more interesting if the spinning top was leaning to the side a bit  like captured at when it almost stops spinning. Great shot either way.</td>', 'Just a thought  image may have been even more interesting if the spinning top was leaning to the side a bit  like captured at when it almost stops spinning. Great shot either way.', '2008-01-29 19:11:07.000000', NULL, 1),
(4437465, 636518, 24550, '<td valign="top">would have preferred a bit more depth of field.</td>', 'would have preferred a bit more depth of field.', '2008-01-29 19:11:10.000000', NULL, 1),
