(4437817, 634155, 88756, '<td valign="top">This took me back- Thanks</td>', 'This took me back- Thanks', '2008-01-29 21:58:22.000000', NULL, 1),
(4437845, 636743, 89277, '<td valign="top">I like the lighting, and the shot is well composed, but I think it looks like a product shot for the peanut butter and jelly. Also, the angle is pretty standard.</td>', 'I like the lighting, and the shot is well composed, but I think it looks like a product shot for the peanut butter and jelly. Also, the angle is pretty standard.', '2008-01-29 22:13:54.000000', NULL, 1),
(4437851, 635320, 89277, '<td valign="top">It seems a little too clean to be for childhood to me. I do like the fading light/fading memories idea though, very clever. I think it might have been more effective to use a warmer light though, but that''s just me</td>', 'It seems a little too clean to be for childhood to me. I do like the fading light/fading memories idea though, very clever. I think it might have been more effective to use a warmer light though, but that''s just me', '2008-01-29 22:15:07.000000', NULL, 1),
(4437852, 636877, 89277, '<td valign="top">Aww, I really like the textures and warm colors on this. Also the pose is really cute. I think that maybe if you re-composed the shot it could be even better.</td>', 'Aww, I really like the textures and warm colors on this. Also the pose is really cute. I think that maybe if you re-composed the shot it could be even better.', '2008-01-29 22:15:48.000000', NULL, 1),
(4437856, 636965, 89277, '<td valign="top">I think this shot has too much going on. It''s sort of confusing because there isn''t a dominant color, and I don''t understand why the things that are in focus are in focus. Also, I really don''t like the light.</td>', 'I think this shot has too much going on. It''s sort of confusing because there isn''t a dominant color, and I don''t understand why the things that are in focus are in focus. Also, I really don''t like the light.', '2008-01-29 22:17:41.000000', NULL, 1),
(4437858, 637092, 89277, '<td valign="top">While a nice feeling, I think this shot would be improved by setting the camera on a longer exposure and at a more exciting angle. I like the message, but the picture is a little too cluttered for me.</td>', 'While a nice feeling, I think this shot would be improved by setting the camera on a longer exposure and at a more exciting angle. I like the message, but the picture is a little too cluttered for me.', '2008-01-29 22:18:36.000000', NULL, 1),
(4437861, 637075, 89277, '<td valign="top">I really like this one, but I don''t understand why you chose to focus it in the bottom left.</td>', 'I really like this one, but I don''t understand why you chose to focus it in the bottom left.', '2008-01-29 22:19:06.000000', NULL, 1),
(4437862, 636452, 89277, '<td valign="top">This one seems very bland. What feeling are you trying to capture?</td>', 'This one seems very bland. What feeling are you trying to capture?', '2008-01-29 22:19:44.000000', NULL, 1),
(4437863, 636865, 89277, '<td valign="top">I don''t like this because I can barely tell what''s going on. I do like the lighting, but it''s confusing and there is not much to look at, and it''s not abstract enough to figure out. I don''t know, that''s just me</td>', 'I don''t like this because I can barely tell what''s going on. I do like the lighting, but it''s confusing and there is not much to look at, and it''s not abstract enough to figure out. I don''t know, that''s just me', '2008-01-29 22:20:28.000000', NULL, 1),
(4437864, 636973, 89277, '<td valign="top">I really don''t like the overexposing that happened in this picture. The composition and idea are nice, but the colors seem off.</td>', 'I really don''t like the overexposing that happened in this picture. The composition and idea are nice, but the colors seem off.', '2008-01-29 22:20:58.000000', NULL, 1),
(4437915, 634288, 54645, '<td valign="top">I like the lighting</td>', 'I like the lighting', '2008-01-29 22:41:40.000000', NULL, 1),
